insert into vehicle_models (id, slug, type, brand, name, engine_cc, seats, transmission, min_age, price_8h_cents, price_day_cents, price_week_cents, deposit_cents, images, content, sort) values ('00000000-0000-4000-8000-000000000101', 'honda-trx420', 'atv', 'Honda', 'TRX420 Rancher', 420, 2, 'automatic', 18, 7500, 8500, null, 50000, '{}'::text[], '{"en":{"tagline":"The Santa Teresa classic. Bulletproof, automatic, room for two.","description":"The Honda TRX420 is the most popular quad on the Nicoya Peninsula for a reason: automatic shifting, a soft ride on washboard dirt roads and enough torque to carry two surfers and their boards up the hill to Mal País. Perfect for beach hopping, grocery runs and sunset missions.","highlights":["Automatic — no clutch","Rides two comfortably","Surf-rack ready","Helmets and lock box included"],"seoTitle":"Honda TRX420 ATV Rental Santa Teresa — from $75","seoDescription":"Rent a Honda TRX420 automatic ATV in Santa Teresa, Costa Rica. Free delivery to Mal País & Playa Carmen, helmets included, instant online booking."},"es":{"tagline":"El clásico de Santa Teresa. Indestructible, automático y para dos.","description":"La Honda TRX420 es el cuadraciclo más popular de la Península de Nicoya: cambios automáticos, suspensión suave en caminos de lastre y fuerza de sobra para dos surfistas con sus tablas. Ideal para recorrer playas, ir al súper y perseguir atardeceres.","highlights":["Automático — sin clutch","Cómodo para dos","Listo para portatablas","Cascos y caja con candado incluidos"],"seoTitle":"Alquiler de Cuadraciclo Honda TRX420 en Santa Teresa — desde $75","seoDescription":"Alquila un cuadraciclo Honda TRX420 automático en Santa Teresa, Costa Rica. Entrega gratis en Mal País y Playa Carmen, cascos incluidos, reserva en línea."}}'::jsonb, 1) on conflict (id) do nothing;
