insert into vehicle_models (id, slug, type, brand, name, engine_cc, seats, transmission, min_age, price_8h_cents, price_day_cents, price_week_cents, deposit_cents, images, content, sort) values ('00000000-0000-4000-8000-000000000102', 'honda-trx520', 'atv', 'Honda', 'TRX520 Foreman', 520, 2, 'semi-automatic', 21, 8500, 9500, null, 50000, '{}'::text[], '{"en":{"tagline":"Big-bore power for the steep jungle climbs.","description":"Our flagship quad. The TRX520 Foreman pulls hard up the rutted climbs toward Cóbano and Montezuma and stays planted in rainy-season mud. Electric shift, 4x4 and extra ground clearance for riders who want to go further.","highlights":["520cc 4x4","Electric shift","Best for hills & mud","Two-up capable"],"seoTitle":"Honda TRX520 4x4 ATV Rental Santa Teresa — from $85","seoDescription":"Rent the most powerful quad in town: Honda TRX520 4x4 in Santa Teresa, Costa Rica. Free delivery, helmets included, book and pay online in minutes."},"es":{"tagline":"Potencia de sobra para las subidas de la jungla.","description":"Nuestro cuadraciclo insignia. La TRX520 Foreman sube sin problema las cuestas hacia Cóbano y Montezuma y se mantiene firme en el barro de la época lluviosa. Cambios eléctricos, 4x4 y mayor despeje para quienes quieren llegar más lejos.","highlights":["520cc 4x4","Cambios eléctricos","Ideal para cuestas y barro","Apto para dos personas"],"seoTitle":"Alquiler de Cuadraciclo Honda TRX520 4x4 en Santa Teresa — desde $85","seoDescription":"Alquila el cuadraciclo más potente: Honda TRX520 4x4 en Santa Teresa, Costa Rica. Entrega gratis, cascos incluidos, reserva y paga en línea."}}'::jsonb, 2) on conflict (id) do nothing;
