insert into vehicle_models (id, slug, type, brand, name, engine_cc, seats, transmission, min_age, price_8h_cents, price_day_cents, price_week_cents, deposit_cents, images, content, sort) values ('00000000-0000-4000-8000-000000000103', 'kymco-mxu-300', 'atv', 'Kymco', 'MXU 300', 300, 2, 'automatic', 18, 7000, 8000, null, 50000, '{}'::text[], '{"en":{"tagline":"Easy-riding automatic quad — the smart-money pick.","description":"Light, nimble and fully automatic, the Kymco MXU 300 is the easiest quad to learn on. Great for first-timers, town cruising and beach runs between Santa Teresa, Playa Hermosa and Mal País.","highlights":["Fully automatic","Easiest to ride","Best value","Helmets included"],"seoTitle":"Cheap ATV Rental Santa Teresa — Kymco MXU 300 from $70","seoDescription":"Affordable automatic quad rental in Santa Teresa, Costa Rica. Kymco MXU 300 from $70, free delivery to your hotel, instant online booking."},"es":{"tagline":"Cuadraciclo automático y fácil de manejar — la opción inteligente.","description":"Ligero, ágil y totalmente automático, el Kymco MXU 300 es el cuadraciclo más fácil para aprender. Perfecto para principiantes, moverse por el pueblo y recorrer las playas entre Santa Teresa, Playa Hermosa y Mal País.","highlights":["Totalmente automático","El más fácil de manejar","Mejor precio","Cascos incluidos"],"seoTitle":"Alquiler de Cuadraciclo Barato en Santa Teresa — Kymco MXU 300 desde $70","seoDescription":"Alquiler de cuadraciclo automático económico en Santa Teresa, Costa Rica. Kymco MXU 300 desde $70, entrega gratis en tu hotel, reserva en línea."}}'::jsonb, 3) on conflict (id) do nothing;
