insert into vehicle_models (id, slug, type, brand, name, engine_cc, seats, transmission, min_age, price_8h_cents, price_day_cents, price_week_cents, deposit_cents, images, content, sort) values ('00000000-0000-4000-8000-000000000201', 'honda-crf300l', 'dirtbike', 'Honda', 'CRF300L', 300, 2, 'manual', 21, 8000, 9000, null, 50000, '{}'::text[], '{"en":{"tagline":"Street-legal dual-sport built for the peninsula''s back roads.","description":"The Honda CRF300L is the ultimate way to explore the Nicoya Peninsula: light enough for river crossings and jungle single-track, comfortable enough for the long run to Montezuma or Cabuya. Fuel-injected, six-speed and fully street legal.","highlights":["Street legal dual-sport","6-speed, fuel injected","Long-range comfort","Helmet included"],"seoTitle":"Dirt Bike Rental Santa Teresa — Honda CRF300L from $80","seoDescription":"Rent a Honda CRF300L dual-sport motorcycle in Santa Teresa, Costa Rica. Street legal, free delivery, helmet included. Book online now."},"es":{"tagline":"Doble propósito, legal para calle, hecha para los caminos de la península.","description":"La Honda CRF300L es la mejor manera de explorar la Península de Nicoya: liviana para cruzar ríos y senderos de montaña, cómoda para el viaje largo a Montezuma o Cabuya. Inyección electrónica, seis velocidades y totalmente legal para calle.","highlights":["Doble propósito legal para calle","6 velocidades, inyección","Cómoda para distancias largas","Casco incluido"],"seoTitle":"Alquiler de Moto de Montaña en Santa Teresa — Honda CRF300L desde $80","seoDescription":"Alquila una moto doble propósito Honda CRF300L en Santa Teresa, Costa Rica. Legal para calle, entrega gratis, casco incluido. Reserva en línea."}}'::jsonb, 10) on conflict (id) do nothing;
