insert into vehicle_models (id, slug, type, brand, name, engine_cc, seats, transmission, min_age, price_8h_cents, price_day_cents, price_week_cents, deposit_cents, images, content, sort) values ('00000000-0000-4000-8000-000000000202', 'honda-crf250f', 'dirtbike', 'Honda', 'CRF250F', 250, 1, 'manual', 18, 7000, 8000, null, 50000, '{}'::text[], '{"en":{"tagline":"Pure trail bike. Light, tough and made for dirt.","description":"The CRF250F is a trail-focused dirt bike with a smooth, forgiving engine and plush suspension — ideal for the muddy jungle tracks behind Santa Teresa and for our guided enduro missions.","highlights":["Trail-tuned suspension","Electric start","Forgiving power","Great for guided tours"],"seoTitle":"Honda CRF250F Dirt Bike Rental Santa Teresa — from $70","seoDescription":"Rent a Honda CRF250F trail dirt bike in Santa Teresa, Costa Rica. Perfect for jungle trails and enduro tours. Free delivery, book online."},"es":{"tagline":"Moto de trail pura. Liviana, resistente y hecha para el barro.","description":"La CRF250F es una moto de trail con motor suave y suspensión cómoda — ideal para los senderos lodosos detrás de Santa Teresa y para nuestras misiones guiadas de enduro.","highlights":["Suspensión para trail","Arranque eléctrico","Potencia amigable","Ideal para tours guiados"],"seoTitle":"Alquiler de Moto Honda CRF250F en Santa Teresa — desde $70","seoDescription":"Alquila una moto de trail Honda CRF250F en Santa Teresa, Costa Rica. Perfecta para senderos y tours de enduro. Entrega gratis, reserva en línea."}}'::jsonb, 11) on conflict (id) do nothing;
