insert into vehicle_models (id, slug, type, brand, name, engine_cc, seats, transmission, min_age, price_8h_cents, price_day_cents, price_week_cents, deposit_cents, images, content, sort) values ('00000000-0000-4000-8000-000000000203', 'honda-xr190', 'dirtbike', 'Honda', 'XR190L', 190, 2, 'manual', 18, 6000, 7000, null, 30000, '{}'::text[], '{"en":{"tagline":"The local''s choice — simple, frugal, goes anywhere.","description":"Every surfer in town seems to ride one: the Honda XR190L is light, sips fuel and shrugs off potholes. A great long-term rental for living the Santa Teresa life.","highlights":["Excellent fuel economy","Light and easy","Great long-term rate","Helmet included"],"seoTitle":"Motorcycle Rental Santa Teresa — Honda XR190 from $60","seoDescription":"Rent a Honda XR190 motorcycle in Santa Teresa, Costa Rica. Cheap, reliable, great weekly and monthly rates. Free delivery, book online."},"es":{"tagline":"La favorita de los locales — sencilla, económica y va a todos lados.","description":"Parece que todo surfista del pueblo anda en una: la Honda XR190L es liviana, gasta poco y no le teme a los huecos. Excelente para alquileres largos y vivir la vida de Santa Teresa.","highlights":["Muy económica","Liviana y fácil","Excelente tarifa semanal","Casco incluido"],"seoTitle":"Alquiler de Moto en Santa Teresa — Honda XR190 desde $60","seoDescription":"Alquila una moto Honda XR190 en Santa Teresa, Costa Rica. Económica, confiable y con tarifas semanales y mensuales. Entrega gratis."}}'::jsonb, 12) on conflict (id) do nothing;
