insert into vehicle_models (id, slug, type, brand, name, engine_cc, seats, transmission, min_age, price_8h_cents, price_day_cents, price_week_cents, deposit_cents, images, content, sort) values ('00000000-0000-4000-8000-000000000301', 'honda-navi', 'scooter', 'Honda', 'Navi 110', 110, 1, 'automatic', 18, 4500, 5500, null, 30000, '{}'::text[], '{"en":{"tagline":"Twist-and-go mini bike for cruising town.","description":"The Honda Navi is a fun, fully automatic mini-bike — perfect for short hops between your villa, the beach and the cafés on the main road.","highlights":["Automatic","Super easy","Cheapest way around town","Helmet included"],"seoTitle":"Scooter Rental Santa Teresa — Honda Navi from $45","seoDescription":"Rent a Honda Navi automatic scooter in Santa Teresa, Costa Rica from $45. Free delivery, helmet included, book online."},"es":{"tagline":"Mini moto automática para moverse por el pueblo.","description":"La Honda Navi es una mini moto divertida y totalmente automática — perfecta para ir de tu villa a la playa y a los cafés de la calle principal.","highlights":["Automática","Súper fácil","La forma más barata de moverse","Casco incluido"],"seoTitle":"Alquiler de Scooter en Santa Teresa — Honda Navi desde $45","seoDescription":"Alquila una scooter automática Honda Navi en Santa Teresa, Costa Rica desde $45. Entrega gratis, casco incluido, reserva en línea."}}'::jsonb, 20) on conflict (id) do nothing;
