insert into tours (id, slug, category, duration_hours, overnight, start_time, days_of_week, price_cents, min_pax, max_pax, difficulty, images, content, sort) values ('00000000-0000-4000-8000-000000000501', 'montezuma-waterfall-atv-tour', 'atv-tour', 5, false, '08:30', '{0,1,2,3,4,5,6}'::int[], 16500, 2, 10, 2, '{}'::text[], '{"en":{"title":"Montezuma Waterfall ATV Tour","summary":"Ride jungle roads from Santa Teresa to the famous Montezuma waterfalls, swim, then cruise the coast back.","description":"Our most popular mission. A local guide leads you over the hills from Santa Teresa through Cóbano to Montezuma, where a short hike brings you to the waterfall pools for a swim. Lunch stop in Montezuma village, then back along the coast road with photo stops. Your own quad, all the gear, zero planning.","itinerary":["08:30 — Pickup at your hotel & safety briefing","09:15 — Jungle ride over the hills via Cóbano","10:15 — Hike & swim at Montezuma waterfall","12:00 — Lunch break in Montezuma village","13:30 — Coastal ride back to Santa Teresa"],"includes":["Your own ATV (or ride two-up)","Bilingual local guide","Helmet & goggles","Fuel","Bottled water","Hotel pickup in Santa Teresa / Mal País"],"bring":["Swimsuit & towel","Closed shoes","Sunscreen","Driver''s license","Cash for lunch"],"seoTitle":"Montezuma Waterfall ATV Tour from Santa Teresa — $165","seoDescription":"Guided ATV tour from Santa Teresa to Montezuma waterfall. Swim the falls, ride the jungle, hotel pickup included. Book online with instant confirmation."},"es":{"title":"Tour en Cuadraciclo a la Catarata de Montezuma","summary":"Recorre caminos de montaña desde Santa Teresa hasta las famosas cataratas de Montezuma, nada y regresa por la costa.","description":"Nuestra misión más popular. Un guía local te lleva por las montañas desde Santa Teresa pasando por Cóbano hasta Montezuma, donde una corta caminata te lleva a las pozas de la catarata. Parada para almorzar en el pueblo y regreso por la costa con paradas para fotos.","itinerary":["08:30 — Recogida en tu hotel y charla de seguridad","09:15 — Ruta por la montaña vía Cóbano","10:15 — Caminata y baño en la catarata de Montezuma","12:00 — Almuerzo en Montezuma","13:30 — Regreso por la costa a Santa Teresa"],"includes":["Tu propio cuadraciclo (o en pareja)","Guía local bilingüe","Casco y gafas","Combustible","Agua embotellada","Recogida en Santa Teresa / Mal País"],"bring":["Traje de baño y toalla","Zapatos cerrados","Bloqueador solar","Licencia de conducir","Efectivo para el almuerzo"],"seoTitle":"Tour en Cuadraciclo a la Catarata de Montezuma desde Santa Teresa — $165","seoDescription":"Tour guiado en cuadraciclo desde Santa Teresa a la catarata de Montezuma. Nada en las pozas, recorre la jungla, recogida incluida. Reserva en línea."}}'::jsonb, 1) on conflict (id) do nothing;
insert into tours (id, slug, category, duration_hours, overnight, start_time, days_of_week, price_cents, min_pax, max_pax, difficulty, images, content, sort) values ('00000000-0000-4000-8000-000000000502', 'cabo-blanco-sunset-atv-ride', 'atv-tour', 3, false, '15:00', '{0,1,2,3,4,5,6}'::int[], 11900, 2, 10, 1, '{}'::text[], '{"en":{"title":"Cabo Blanco Sunset ATV Ride","summary":"An easy afternoon ride south to Mal País and the edge of Cabo Blanco, finishing with sunset on the beach.","description":"Perfect for first-time riders. Cruise south through Mal País fishing village toward the Cabo Blanco reserve, stop at hidden tide pools and lookouts, and finish on the sand as the sun drops into the Pacific.","itinerary":["15:00 — Pickup & briefing","15:30 — Ride south through Mal País","16:30 — Tide pools & lookout stops","17:30 — Sunset on the beach","18:00 — Return"],"includes":["Your own ATV (or ride two-up)","Local guide","Helmet","Fuel","Cold drink at sunset"],"bring":["Camera","Light jacket","Driver''s license"],"seoTitle":"Sunset ATV Tour Santa Teresa & Mal País — $119","seoDescription":"Easy guided sunset ATV ride from Santa Teresa to Mal País and Cabo Blanco. Great for beginners. Book online."},"es":{"title":"Atardecer en Cuadraciclo a Cabo Blanco","summary":"Un paseo fácil por la tarde hacia Mal País y Cabo Blanco, terminando con el atardecer en la playa.","description":"Ideal para principiantes. Recorre el pueblo pesquero de Mal País hacia la reserva de Cabo Blanco, con paradas en pozas de marea y miradores, y termina en la arena viendo el sol caer en el Pacífico.","itinerary":["15:00 — Recogida y charla","15:30 — Ruta hacia Mal País","16:30 — Pozas y miradores","17:30 — Atardecer en la playa","18:00 — Regreso"],"includes":["Tu propio cuadraciclo (o en pareja)","Guía local","Casco","Combustible","Bebida fría al atardecer"],"bring":["Cámara","Chaqueta liviana","Licencia de conducir"],"seoTitle":"Tour de Atardecer en Cuadraciclo Santa Teresa y Mal País — $119","seoDescription":"Paseo guiado y fácil al atardecer en cuadraciclo desde Santa Teresa a Mal País y Cabo Blanco. Reserva en línea."}}'::jsonb, 2) on conflict (id) do nothing;
insert into tours (id, slug, category, duration_hours, overnight, start_time, days_of_week, price_cents, min_pax, max_pax, difficulty, images, content, sort) values ('00000000-0000-4000-8000-000000000503', 'jungle-to-coast-full-day-atv', 'atv-tour', 8, false, '08:00', '{0,1,2,3,4,5,6}'::int[], 21000, 2, 8, 3, '{}'::text[], '{"en":{"title":"Jungle to Coast — Full-Day ATV Expedition","summary":"The full Nicoya loop: Montezuma falls, Cabuya, Cabo Blanco coast and Mal País in one epic day.","description":"For riders who want it all. A full day on the peninsula''s best dirt roads with a swim at Montezuma, lunch by the sea in Cabuya, river crossings and remote beaches most visitors never find.","itinerary":["08:00 — Pickup & briefing","09:00 — Montezuma waterfall swim","11:30 — Ride to Cabuya","12:30 — Seafood lunch","14:00 — Back roads & river crossings to Mal País","16:00 — Return"],"includes":["Your own ATV","Guide","Helmet & goggles","Fuel","Lunch","Water & snacks"],"bring":["Swimsuit","Closed shoes","Sunscreen","Driver''s license"],"seoTitle":"Full-Day ATV Tour Nicoya Peninsula from Santa Teresa — $210","seoDescription":"Full-day guided ATV expedition from Santa Teresa: Montezuma waterfall, Cabuya, Cabo Blanco coast. Lunch included. Book online."},"es":{"title":"De la Jungla a la Costa — Expedición de Día Completo","summary":"El circuito completo de Nicoya: catarata de Montezuma, Cabuya, la costa de Cabo Blanco y Mal País en un día épico.","description":"Para quienes lo quieren todo. Un día completo por los mejores caminos de lastre de la península, con baño en Montezuma, almuerzo frente al mar en Cabuya, cruces de río y playas remotas.","itinerary":["08:00 — Recogida y charla","09:00 — Baño en la catarata de Montezuma","11:30 — Ruta a Cabuya","12:30 — Almuerzo de mariscos","14:00 — Caminos y ríos hacia Mal País","16:00 — Regreso"],"includes":["Tu propio cuadraciclo","Guía","Casco y gafas","Combustible","Almuerzo","Agua y snacks"],"bring":["Traje de baño","Zapatos cerrados","Bloqueador","Licencia de conducir"],"seoTitle":"Tour de Día Completo en Cuadraciclo desde Santa Teresa — $210","seoDescription":"Expedición guiada de día completo en cuadraciclo: Montezuma, Cabuya y la costa de Cabo Blanco. Almuerzo incluido."}}'::jsonb, 3) on conflict (id) do nothing;
insert into tours (id, slug, category, duration_hours, overnight, start_time, days_of_week, price_cents, min_pax, max_pax, difficulty, images, content, sort) values ('00000000-0000-4000-8000-000000000511', 'ridge-runner-enduro-tour', 'dirt-bike-tour', 4, false, '07:30', '{1,2,3,4,5,6}'::int[], 18500, 1, 6, 4, '{}'::text[], '{"en":{"title":"Ridge Runner — Guided Enduro Tour","summary":"Half-day guided dirt bike ride on the mountain ridges and jungle single-track above Santa Teresa.","description":"Climb the ridges behind Santa Teresa on proper trail bikes, with ocean views, muddy single-track and river crossings. For riders comfortable with a clutch — your guide adapts the line to the group.","itinerary":["07:30 — Meet & gear up","08:00 — Ridge climbs & lookouts","09:30 — Jungle single-track","10:30 — River crossing & break","11:30 — Return"],"includes":["Honda CRF250F","Expert guide","Helmet, goggles, gloves","Fuel","Water & fruit"],"bring":["Long pants","Boots or sturdy shoes","Motorcycle license"],"seoTitle":"Dirt Bike Tour Santa Teresa — Guided Enduro $185","seoDescription":"Guided half-day enduro dirt bike tour in the mountains above Santa Teresa, Costa Rica. Bikes & gear included. Book online."},"es":{"title":"Ridge Runner — Tour de Enduro Guiado","summary":"Medio día en moto de trail por las crestas y senderos de jungla sobre Santa Teresa.","description":"Sube las crestas detrás de Santa Teresa en motos de trail, con vistas al mar, senderos lodosos y cruces de río. Para quienes manejan con clutch — el guía adapta la ruta al grupo.","itinerary":["07:30 — Encuentro y equipo","08:00 — Crestas y miradores","09:30 — Senderos de jungla","10:30 — Cruce de río y descanso","11:30 — Regreso"],"includes":["Honda CRF250F","Guía experto","Casco, gafas y guantes","Combustible","Agua y fruta"],"bring":["Pantalón largo","Botas o zapatos fuertes","Licencia de moto"],"seoTitle":"Tour en Moto de Montaña Santa Teresa — Enduro Guiado $185","seoDescription":"Tour guiado de enduro de medio día en las montañas de Santa Teresa, Costa Rica. Moto y equipo incluidos."}}'::jsonb, 10) on conflict (id) do nothing;
insert into tours (id, slug, category, duration_hours, overnight, start_time, days_of_week, price_cents, min_pax, max_pax, difficulty, images, content, sort) values ('00000000-0000-4000-8000-000000000512', 'peninsula-enduro-full-day', 'dirt-bike-tour', 8, false, '07:00', '{1,3,5,6}'::int[], 28000, 1, 6, 5, '{}'::text[], '{"en":{"title":"Peninsula Enduro — Full-Day Expedition","summary":"A hard-charging full day across the Nicoya Peninsula''s toughest trails for experienced riders.","description":"Our five-star wanted level. Steep technical climbs, deep river crossings and remote coastline, with lunch in a local soda. Experienced off-road riders only.","itinerary":["07:00 — Gear up","07:30 — Technical ridge trails","12:00 — Lunch at a local soda","13:00 — River & coast section","15:30 — Return"],"includes":["Honda CRF300L or CRF250F","Expert guide + sweep rider","Full protective gear","Fuel","Lunch","Water & snacks"],"bring":["Motorcycle license","Riding experience","Change of clothes"],"seoTitle":"Full-Day Enduro Tour Costa Rica from Santa Teresa — $280","seoDescription":"Full-day expert enduro dirt bike expedition across the Nicoya Peninsula from Santa Teresa. Bikes, gear and lunch included."},"es":{"title":"Enduro de la Península — Expedición de Día Completo","summary":"Un día completo e intenso por los senderos más técnicos de la Península de Nicoya, para pilotos con experiencia.","description":"Nuestro nivel de cinco estrellas. Subidas técnicas, cruces de río profundos y costa remota, con almuerzo en una soda local. Solo para pilotos con experiencia off-road.","itinerary":["07:00 — Equipo","07:30 — Senderos técnicos","12:00 — Almuerzo en una soda","13:00 — Ríos y costa","15:30 — Regreso"],"includes":["Honda CRF300L o CRF250F","Guía experto + piloto de apoyo","Equipo de protección completo","Combustible","Almuerzo","Agua y snacks"],"bring":["Licencia de moto","Experiencia","Muda de ropa"],"seoTitle":"Tour de Enduro de Día Completo en Costa Rica desde Santa Teresa — $280","seoDescription":"Expedición de enduro de día completo por la Península de Nicoya. Moto, equipo y almuerzo incluidos."}}'::jsonb, 11) on conflict (id) do nothing;
insert into tours (id, slug, category, duration_hours, overnight, start_time, days_of_week, price_cents, min_pax, max_pax, difficulty, images, content, sort) values ('00000000-0000-4000-8000-000000000521', 'beach-camp-overnight', 'camping', 26, true, '14:00', '{3,5,6}'::int[], 29000, 2, 8, 2, '{}'::text[], '{"en":{"title":"ATV Beach Camp — Overnight Adventure","summary":"Ride to a remote beach, set up camp, cook dinner over the fire and sleep to the sound of the waves.","description":"Load the quads and head to a secluded stretch of coast. Your guides set up tents, cook a grilled dinner over the bonfire and wake you with coffee and breakfast on the sand. Optional morning ride before heading home.","itinerary":["14:00 — Pickup & ride out","16:00 — Camp setup & swim","18:00 — Sunset & bonfire dinner","Morning — Coffee, breakfast & beach walk","10:00 — Ride back, home by noon"],"includes":["ATV for the trip","Guide & camp crew","Tents, mats & bedding","Dinner, breakfast & drinks","Headlamps","Fuel"],"bring":["Change of clothes","Swimsuit","Bug spray","Driver''s license"],"seoTitle":"Beach Camping ATV Tour Santa Teresa — Overnight $290","seoDescription":"Overnight ATV beach camping adventure from Santa Teresa, Costa Rica. Tents, bonfire dinner and breakfast included. Book online."},"es":{"title":"Camping de Playa en Cuadraciclo — Aventura Nocturna","summary":"Viaja a una playa remota, arma el campamento, cocina en la fogata y duerme con el sonido de las olas.","description":"Carga los cuadraciclos y dirígete a una playa aislada. Los guías arman las tiendas, cocinan una cena a la parrilla en la fogata y te despiertan con café y desayuno en la arena.","itinerary":["14:00 — Recogida y salida","16:00 — Campamento y baño","18:00 — Atardecer y cena en la fogata","Mañana — Café, desayuno y caminata","10:00 — Regreso, llegada al mediodía"],"includes":["Cuadraciclo para el viaje","Guía y equipo de campamento","Tiendas, colchonetas y ropa de cama","Cena, desayuno y bebidas","Linternas frontales","Combustible"],"bring":["Muda de ropa","Traje de baño","Repelente","Licencia de conducir"],"seoTitle":"Camping de Playa en Cuadraciclo Santa Teresa — $290","seoDescription":"Aventura de camping en la playa con cuadraciclo desde Santa Teresa, Costa Rica. Tiendas, cena y desayuno incluidos."}}'::jsonb, 20) on conflict (id) do nothing;
insert into tours (id, slug, category, duration_hours, overnight, start_time, days_of_week, price_cents, min_pax, max_pax, difficulty, images, content, sort) values ('00000000-0000-4000-8000-000000000531', 'hidden-beaches-day-tour', 'day-tour', 6, false, '09:00', '{0,1,2,3,4,5,6}'::int[], 17500, 2, 10, 2, '{}'::text[], '{"en":{"title":"Hidden Beaches Day Tour","summary":"Hop between secret coves north and south of Santa Teresa — swim, snorkel the tide pools and eat fresh ceviche.","description":"A laid-back day exploring the coves and tide pools locals keep to themselves, from Playa Hermosa and Manzanillo to the rocky reefs of Mal País. Snorkel gear, ceviche lunch and plenty of swim time.","itinerary":["09:00 — Pickup","09:30 — Playa Hermosa & Manzanillo coves","12:00 — Ceviche lunch","13:00 — Mal País tide pools & snorkel","15:00 — Return"],"includes":["ATV transport","Guide","Snorkel gear","Lunch","Water & fruit"],"bring":["Swimsuit & towel","Reef-safe sunscreen","Driver''s license"],"seoTitle":"Santa Teresa Beach Tour — Hidden Beaches by ATV $175","seoDescription":"Day tour to the hidden beaches and tide pools around Santa Teresa and Mal País by ATV. Snorkel & lunch included."},"es":{"title":"Tour de Playas Escondidas","summary":"Recorre calas secretas al norte y sur de Santa Teresa — nada, haz snorkel en las pozas y come ceviche fresco.","description":"Un día relajado explorando calas y pozas que los locales guardan en secreto, desde Playa Hermosa y Manzanillo hasta los arrecifes de Mal País. Equipo de snorkel, almuerzo de ceviche y mucho tiempo para nadar.","itinerary":["09:00 — Recogida","09:30 — Calas de Playa Hermosa y Manzanillo","12:00 — Almuerzo de ceviche","13:00 — Pozas de Mal País y snorkel","15:00 — Regreso"],"includes":["Transporte en cuadraciclo","Guía","Equipo de snorkel","Almuerzo","Agua y fruta"],"bring":["Traje de baño y toalla","Bloqueador amigable con el arrecife","Licencia de conducir"],"seoTitle":"Tour de Playas Santa Teresa — Playas Escondidas en Cuadraciclo $175","seoDescription":"Tour de un día a las playas escondidas y pozas de Santa Teresa y Mal País en cuadraciclo. Snorkel y almuerzo incluidos."}}'::jsonb, 30) on conflict (id) do nothing;
insert into tours (id, slug, category, duration_hours, overnight, start_time, days_of_week, price_cents, min_pax, max_pax, difficulty, images, content, sort) values ('00000000-0000-4000-8000-000000000532', 'bongo-river-manzanillo-day-tour', 'day-tour', 7, false, '08:30', '{0,2,4,6}'::int[], 18500, 2, 8, 3, '{}'::text[], '{"en":{"title":"Bongo River & Manzanillo Day Tour","summary":"Ride north to the Bongo River estuary for wildlife spotting, then Manzanillo''s wild beach for a swim.","description":"Head north up the coast past Playa Hermosa to the Bongo River, where the guide points out crocodiles, herons and monkeys in the mangroves. Then on to Manzanillo''s long wild beach for lunch and a swim.","itinerary":["08:30 — Pickup","09:30 — Bongo River mangroves & wildlife","12:00 — Lunch near Manzanillo","13:00 — Beach time","15:30 — Return"],"includes":["ATV","Naturalist guide","Helmet","Fuel","Lunch","Water"],"bring":["Binoculars (optional)","Swimsuit","Bug spray","Driver''s license"],"seoTitle":"Bongo River & Manzanillo Tour from Santa Teresa — $185","seoDescription":"ATV day tour from Santa Teresa to the Bongo River mangroves and Manzanillo beach. Wildlife, lunch and swim included."},"es":{"title":"Tour Río Bongo y Manzanillo","summary":"Viaja al norte hasta el estuario del Río Bongo para ver fauna y luego a la playa salvaje de Manzanillo.","description":"Sube por la costa pasando Playa Hermosa hasta el Río Bongo, donde el guía te muestra cocodrilos, garzas y monos en el manglar. Luego a la larga playa de Manzanillo para almorzar y nadar.","itinerary":["08:30 — Recogida","09:30 — Manglar del Río Bongo y fauna","12:00 — Almuerzo cerca de Manzanillo","13:00 — Tiempo de playa","15:30 — Regreso"],"includes":["Cuadraciclo","Guía naturalista","Casco","Combustible","Almuerzo","Agua"],"bring":["Binoculares (opcional)","Traje de baño","Repelente","Licencia de conducir"],"seoTitle":"Tour Río Bongo y Manzanillo desde Santa Teresa — $185","seoDescription":"Tour de un día en cuadraciclo desde Santa Teresa al manglar del Río Bongo y la playa de Manzanillo."}}'::jsonb, 31) on conflict (id) do nothing;
